define("mod_learninglog/scrollfade",[],function(){return{init:function(){var e=document.querySelectorAll(".learninglog-fade-in");if(!e.length)return;var n=new IntersectionObserver(function(e){e.forEach(function(e){e.isIntersecting&&e.target.classList.add("learninglog-visible")})},{rootMargin:"0px 0px -40px 0px",threshold:.05});e.forEach(function(e){n.observe(e)})}}});
